        //
        // stat attrs
        //

        .device = fe->device,
        .inode = fe->inode,
        .nlink = fe->nlink,
        .flags = fe->flags,

        //
        // file size
        //

        .size = fe->size,
    };

    //
    // first and last characters
    //

    FILE* f = fopen(fe->path, "r");
    if (!f) {
        /*
        PROGRESS_LOCK(ctx->progress, &ctx->progress_mutex, {
            clear_progress();
            fprintf(stderr, "failed to open %s\n", fm->path);
            perror("open(2)");
        });
        */
        return NULL;
    }

    int c = fgetc(f);
    if (c < 0) {
        /*
        PROGRESS_LOCK(ctx->progress, &ctx->progress_mutex, {
            fprintf(stderr, "failed read first byte %s\n", fm.path);
            perror("fgetc(3)");
        });
        */
        return NULL;
    }
    fm.first = c;

    if (fseek(f, -1, SEEK_END) < 0) {
        /*
        PROGRESS_LOCK(ctx->progress, &ctx->progress_mutex, {
            fprintf(stderr, "failed seek %s\n", fm.path);
            perror("fseek(3)");
        });
        */
        return NULL;
    }

    c = fgetc(f);
    if (c < 0) {
        /*
        PROGRESS_LOCK(ctx->progress, &ctx->progress_mutex, {
            fprintf(stderr, "failed read last byte %s\n", fm.path);
            perror("fgetc(3)");
        });
        */
        return NULL;
    }
    fclose(f);

    fm.last = c;

    //
    // file real path
    //

    fm.path = fe->path;

    //
    // get clone id
    //

    fm.clone_id = get_clone_id(fe->path);

    return metadata_dup(&fm);
}

